import java.util.*;
import java.util.stream.Collectors;

public class Main {
    public static void main(String[] args) {

        // Try modifying this ArrayList playground!
        List<Integer> numbers = new ArrayList<>(Arrays.asList(5, 3, 8, 1, 9, 2, 7, 4, 6));
        System.out.println("Original : " + numbers);

        // Sort ascending
        Collections.sort(numbers);
        System.out.println("Sorted   : " + numbers);

        // Filter even numbers using Stream
        List<Integer> evens = numbers.stream()
            .filter(n -> n % 2 == 0)
            .collect(Collectors.toList());
        System.out.println("Evens    : " + evens);

        // Sum using stream
        int sum = numbers.stream().mapToInt(Integer::intValue).sum();
        System.out.println("Sum      : " + sum);

        // Remove numbers less than 5
        numbers.removeIf(n -> n < 5);
        System.out.println("After removeIf(<5): " + numbers);
    }
}

